r"""
Generates 300 questions across 6 categories for Chapter 03 (Two Cats and the Monkey) — Book 3
"""
import os
BASE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CH_DIR = os.path.join(BASE_DIR, "question_bank", "chapter_03")
os.makedirs(CH_DIR, exist_ok=True)
CH_ID = "BK03_CH03"
CH_TITLE = "Two Cats and the Monkey"

# ── 1. MCQs (50) ──
mcqs = [
    ("What did the two cats find on the street?","(A) A roti","(B) A fish","(C) A cheese","(D) A bread loaf","(A)","They found a roti lying on the street.","Easy","Remembering","Discovery"),
    ("What is 'Two Cats and the Monkey' based on?","(A) A Panchatantra Tale","(B) A Greek Myth","(C) A Modern Novel","(D) A Science Report","(A)","It is a Panchatantra Tale.","Easy","Remembering","Genre"),
    ("What were the two cats doing before they found the roti?","(A) Frolicking on the road","(B) Sleeping in a house","(C) Fishing in a pond","(D) Climbing a mountain","(A)","They were frolicking on the road.","Easy","Remembering","Activity"),
    ("What did the cats decide to do with the roti?","(A) Share it equally between themselves","(B) Give it to the monkey","(C) Throw it away","(D) Hide it in a tree","(A)","They decided to share equally.","Easy","Remembering","Decision"),
    ("Why did the cats start arguing?","(A) Each thought the other got the bigger part","(B) They wanted different flavours","(C) They could not find the roti","(D) A dog stole the roti","(A)","Each claimed the other got a bigger piece.","Easy","Remembering","Conflict"),
    ("Who did the cats choose as their judge?","(A) A monkey","(B) A dog","(C) A human","(D) A bird","(A)","They chose a monkey sitting on a wall.","Easy","Remembering","Judge"),
    ("Where was the monkey sitting when the cats found him?","(A) On a wall","(B) In a tree","(C) On the road","(D) In the river","(A)","The monkey was sitting on a wall.","Easy","Remembering","Location"),
    ("Had the monkey observed the cats' fight?","(A) Yes, he had been watching for some time","(B) No, he was sleeping","(C) No, he just arrived","(D) He was reading a book","(A)","He had observed their fight.","Easy","Remembering","Observation"),
    ("What was the monkey really looking for?","(A) An opportunity to grab the roti for himself","(B) A chance to help the cats","(C) A new home","(D) Other monkeys to play with","(A)","He wanted to grab the roti for himself.","Easy","Understanding","Motive"),
    ("How did the monkey pretend to judge the roti?","(A) He lifted both parts, compared them, and took bites from each","(B) He weighed them on a scale","(C) He measured them with a ruler","(D) He asked other animals for opinions","(A)","He lifted, compared, and took bites.","Easy","Remembering","Method"),
    ("What excuse did the monkey give for taking bites?","(A) He said one portion was bigger and needed to be made equal","(B) He was testing for poison","(C) He was very hungry and asked permission","(D) He wanted to check the taste for quality","(A)","He said one portion was bigger.","Easy","Remembering","Excuse"),
    ("What happened to the roti in the end?","(A) The monkey gobbled up the entire roti","(B) The cats shared it equally","(C) It fell into a river","(D) A bird took it away","(A)","The monkey ate the entire roti.","Easy","Remembering","Outcome"),
    ("How did the cats watch the monkey eat their roti?","(A) Helplessly","(B) Happily","(C) Angrily and fought the monkey","(D) They did not notice","(A)","They could only look helplessly.","Easy","Remembering","Reaction"),
    ("What did the monkey do after eating all the roti?","(A) Jumped back on the wall and vanished","(B) Thanked the cats","(C) Fell asleep","(D) Gave them another roti","(A)","He jumped on the wall and vanished.","Easy","Remembering","Departure"),
    ("Did the cats get any roti to eat?","(A) No, they did not get even a single bite","(B) Yes, they each got half","(C) Yes, the monkey gave them crumbs","(D) They found another roti","(A)","They did not get even a single bite.","Easy","Remembering","Final Share"),
    ("What did the cats realise at the end?","(A) They were foolish to fight and trust a stranger","(B) Monkeys are the best judges","(C) Fighting is fun","(D) They should have hidden the roti","(A)","Foolish to fight and trust a stranger.","Easy","Understanding","Lesson Learned"),
    ("What is the moral of the story?","(A) Fighting amongst yourselves allows others to take advantage of you","(B) Always trust monkeys","(C) Never share food","(D) Fighting makes you stronger","(A)","Fighting allows others to take advantage.","Easy","Remembering","Moral"),
    ("What does 'frolicking' mean?","(A) To behave in a playful way","(B) To fight aggressively","(C) To sleep deeply","(D) To swim in water","(A)","Frolicking means behaving playfully.","Easy","Understanding","Vocabulary"),
    ("What does 'neutral' mean?","(A) Not supporting either side in an argument","(B) Very angry","(C) Extremely happy","(D) Supporting one side only","(A)","Not supporting either side.","Easy","Understanding","Vocabulary"),
    ("What does 'gobbled up' mean?","(A) Ate quickly and greedily","(B) Threw away carefully","(C) Cooked slowly","(D) Shared generously","(A)","Ate quickly and greedily.","Easy","Understanding","Vocabulary"),
    ("Why did the cats need a judge?","(A) They could not agree on whether the pieces were equal","(B) They wanted entertainment","(C) It was a rule of the village","(D) The monkey offered himself","(A)","Could not agree on equality of pieces.","Easy","Understanding","Need for Judge"),
    ("How did the first cat describe the roti division?","(A) The second cat got the bigger part which was unfair","(B) The roti was perfectly equal","(C) Both pieces were too small","(D) The roti was burnt","(A)","Said the other got the bigger, unfair part.","Easy","Remembering","Complaint"),
    ("What did the second cat say in response?","(A) That it was untrue — she did not get the bigger part","(B) She agreed and gave some back","(C) She ran away with the roti","(D) She asked a dog to judge","(A)","Said it was untrue.","Easy","Remembering","Counter-claim"),
    ("Were the cats friends before the argument?","(A) Yes, they were friends","(B) No, they were enemies","(C) They had never met before","(D) They were siblings","(A)","The cats were friends.","Easy","Remembering","Relationship"),
    ("What title is given to Chapter 03?","(A) Two Cats and the Monkey","(B) The Jackal and the Dhol","(C) The Foolish Pandit","(D) Fountain Pen","(A)","Two Cats and the Monkey.","Easy","Remembering","Title"),
    # Medium
    ("Why did the monkey readily agree to be the judge?","(A) He saw an opportunity to cheat the cats and eat the roti himself","(B) He was a trained judge","(C) He genuinely wanted to help","(D) The cats forced him","(A)","He wanted to cheat them and eat the roti.","Medium","Analyzing","Monkey's Motive"),
    ("How does the monkey exploit the cats' dispute for his own benefit?","(A) By pretending to make portions equal while actually eating the entire roti bite by bite","(B) By running away immediately","(C) By calling other animals","(D) By giving them advice","(A)","Pretending to equalize while eating everything.","Medium","Analyzing","Exploitation"),
    ("What is the irony in the cats choosing the monkey as a 'neutral judge'?","(A) The judge was never neutral — he was a self-interested cheat who used their trust","(B) The monkey was actually fair","(C) The cats won in the end","(D) There is no irony","(A)","The judge was self-interested, not neutral.","Medium","Analyzing","Irony"),
    ("How does internal fighting weaken a group according to this story?","(A) When friends fight amongst themselves, they become vulnerable to exploitation by outsiders","(B) Fighting makes them physically stronger","(C) Fighting has no effect on the group","(D) Fighting helps them find better food","(A)","Internal conflict makes groups vulnerable.","Medium","Evaluating","Theme Analysis"),
    ("What could the cats have done instead of fighting?","(A) Trusted each other, accepted the slight difference, or measured the pieces together","(B) Thrown the roti away","(C) Given the entire roti to the monkey","(D) Eaten the roti without sharing","(A)","Trusted each other or measured together.","Medium","Applying","Alternative Action"),
    ("Compare the monkey's cunning with the jackal's foolishness in Chapter 02.","(A) The monkey used cleverness to exploit others; the jackal used foolishness that hurt only himself","(B) Both were equally foolish","(C) Both were equally wise","(D) Neither story has animal characters","(A)","Monkey: clever exploitation. Jackal: self-harming foolishness.","Medium","Comparing","Cross-Chapter"),
    ("What lesson does the story teach about trusting strangers with personal disputes?","(A) Strangers may have their own agenda and exploit your vulnerability during disputes","(B) Always trust strangers completely","(C) Strangers always give the best advice","(D) Personal disputes should always involve strangers","(A)","Strangers may exploit vulnerability.","Medium","Evaluating","Trust Lesson"),
    ("How does the monkey maintain his deception throughout the judging process?","(A) By repeatedly claiming one piece is bigger, taking a bite each time, creating an endless cycle until the roti is gone","(B) By weighing pieces on a scale","(C) By dividing fairly","(D) By asking the cats to close their eyes","(A)","Endless cycle of 'one is bigger' + bites.","Medium","Analyzing","Deception Technique"),
    ("Why were the cats 'helpless' while the monkey ate their roti?","(A) They had given him authority as judge and could not challenge his method","(B) The monkey was too strong","(C) They fell asleep","(D) A cage trapped them","(A)","They had ceded authority to him.","Medium","Understanding","Power Dynamic"),
    ("What does 'vanished from there' tell us about the monkey's character?","(A) He had no guilt or loyalty — he took what he wanted and disappeared without remorse","(B) He was a magician","(C) He went home to share the roti","(D) He felt sorry and came back later","(A)","No guilt, took what he wanted and left.","Medium","Analyzing","Character Analysis"),
    ("How does this story apply to real-world situations of sibling rivalry?","(A) When siblings fight over things, parents or others may end up deciding, and both may lose out","(B) Siblings should always fight","(C) Siblings never share anything","(D) This story only applies to animals","(A)","Sibling fights can result in both losing.","Medium","Applying","Real-World Application"),
    ("What quality did the cats lack that led to their loss?","(A) Trust in each other and ability to compromise","(B) Physical strength","(C) Speed and agility","(D) Intelligence about cooking","(A)","Lacked trust and compromise ability.","Medium","Evaluating","Character Weakness"),
    ("Why is the moral 'Fighting allows others to take advantage' universally important?","(A) In any group — family, school, nation — internal conflict creates opportunities for outsiders to exploit","(B) It only applies to cats","(C) Fighting is always good","(D) It has no modern relevance","(A)","Universal: internal conflict invites exploitation.","Medium","Evaluating","Universal Relevance"),
    ("How does the story show that a small disagreement can lead to total loss?","(A) A tiny difference in roti size escalated to a fight, which led to losing the entire roti to the monkey","(B) The cats gained more roti","(C) The disagreement was resolved peacefully","(D) Nothing was lost","(A)","Small difference → fight → total loss.","Medium","Analyzing","Escalation"),
    ("What is the significance of the cats being friends at the start?","(A) It emphasises that even friends can lose everything when they let disputes override their bond","(B) It has no significance","(C) It means they were never close","(D) It proves friends should never share food","(A)","Even friends lose when disputes override bonds.","Medium","Analyzing","Friendship Theme"),
    # Hard
    ("Analyse the power dynamics between the cats and the monkey.","(A) The cats voluntarily surrendered their power to the monkey by making him judge, enabling their own exploitation","(B) The monkey had legal authority","(C) The cats were physically weaker","(D) There were no power dynamics","(A)","Cats surrendered power voluntarily.","Hard","Analyzing","Power Dynamics"),
    ("Evaluate the story's commentary on third-party intervention in personal disputes.","(A) Third parties may have hidden agendas; resolving disputes internally is safer than ceding control to outsiders","(B) Third parties always help","(C) You should never resolve disputes yourself","(D) The story has no commentary on this","(A)","Third parties may have hidden agendas.","Hard","Evaluating","Social Commentary"),
    ("Compare this story with the English proverb 'United we stand, divided we fall'.","(A) Both convey that internal division leads to collapse and exploitation, while unity preserves strength and resources","(B) They teach opposite lessons","(C) The proverb is about architecture","(D) There is no connection","(A)","Internal division → collapse; unity → strength.","Hard","Comparing","Proverbial Parallel"),
    ("Synthesise how Chapters 01-03 build a progressive wisdom curriculum.","(A) Ch01: Think before acting. Ch02: Gather info before acting. Ch03: Stay united, don't let disputes invite exploitation. Progressive: Thought → Evidence → Unity","(B) They teach only about animals","(C) They repeat the same lesson","(D) They have no connection","(A)","Progressive: Thought → Evidence → Unity.","Hard","Synthesizing","Curriculum Design"),
    ("Critique the monkey's ethics from a moral philosophy perspective.","(A) The monkey represents opportunistic self-interest without regard for justice or fairness — a cautionary example of unchecked selfishness","(B) The monkey was ethically correct","(C) Ethics do not apply to animals","(D) The monkey was the true victim","(A)","Opportunistic self-interest, cautionary example.","Hard","Evaluating","Ethical Critique"),
    ("How does this story function as an allegory for political exploitation?","(A) When citizens fight amongst themselves, corrupt leaders (the monkey) exploit their division for personal gain","(B) It is about cooking","(C) It has no political meaning","(D) The monkey represents democracy","(A)","Internal citizen conflict enables corrupt exploitation.","Hard","Analyzing","Political Allegory"),
    ("Design a role-play activity for Class 3 students based on this chapter.","(A) Three students play the two cats and the monkey; they act out the dispute, the judging, and the loss, then discuss how they could have resolved it differently","(B) Students just read the story silently","(C) Students draw pictures of monkeys","(D) Students memorise the story word by word","(A)","Role-play dispute, judging, loss; discuss alternatives.","Hard","Creating","Pedagogical Design"),
    ("Assess how the story develops emotional intelligence in young readers.","(A) It teaches recognising exploitation, valuing compromise, controlling anger during disputes, and choosing trustworthy mediators","(B) It only teaches reading skills","(C) It has no emotional content","(D) It makes children afraid of monkeys","(A)","Recognise exploitation, value compromise, control anger.","Hard","Evaluating","Emotional Intelligence"),
    ("Formulate the ultimate lesson of Chapter 03 as a life principle.","(A) Unity and trust between friends is more valuable than any material possession — resolve disputes internally before outsiders exploit your division","(B) Always let strangers solve your problems","(C) Never share anything with anyone","(D) Fighting is the best way to solve problems","(A)","Unity > material possession; resolve disputes internally.","Hard","Creating","Life Principle"),
    ("Synthesise a classroom discussion comparing all three Panchatantra tales (Ch 01-03).","(A) All three teach caution: Ch01 (think before acting), Ch02 (verify before acting), Ch03 (unite before outsiders exploit) — together they build comprehensive wisdom for young learners","(B) They are unrelated stories","(C) Only Chapter 01 has a moral","(D) None of them are Panchatantra tales","(A)","Three pillars: Think + Verify + Unite.","Hard","Synthesizing","Comparative Discussion"),
]

mcq_content = f"# MCQs — Chapter 03: {CH_TITLE}\n\n> **Category**: Multiple Choice Questions | **Total**: 50 Questions | **Marks**: 1 each\n\n---\n\n"
for idx, (q,a,b,c,d,ans,exp,diff,bloom,topic) in enumerate(mcqs,1):
    mcq_content += f"### Question {idx}\n- **Question ID**: {CH_ID}_MCQ_{idx:03d}\n- **Difficulty**: {diff}\n- **Bloom Level**: {bloom}\n- **Topic**: {topic}\n- **Marks**: 1\n\n**Question**: {q}\n\n- {a}\n- {b}\n- {c}\n- {d}\n\n- **Answer Key**: **{ans}** — {exp}\n\n---\n\n"
with open(os.path.join(CH_DIR, "mcqs.md"), "w", encoding="utf-8") as f: f.write(mcq_content)

